 				assert.EqualError(t, err, tc.err)
 				assert.Nil(t, tmpl)
 			case tc.errf != nil:
 				tc.errf(t, tc.tname, dir, tmpl, err)
 			default:
 				require.NoError(t, err)
 				assert.NotNil(t, tmpl)
 			}
 		})
 	}
 }
